import{_ as a,o,c as t,a2 as c}from"./chunks/framework.C0KMm31j.js";const r="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_util_source_01_boundary.png",d="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_util_source_02_lifecycle_service.png",i="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_util_source_06_service_params.png",n="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_util_source_03_action_state.png",l="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_util_source_04_spatial_grid.png",s="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_util_source_05_odom_validation.png",v=JSON.parse('{"title":"规划、控制、恢复都在借谁的手？逐函数拆解 Nav2 公共底座 nav2_util","description":"打开 Planner Server、Controller Server、Costmap、Lifecycle Manager 或 Waypoint Follower 的源码，经常能看到相同的名字：LifecycleNode、SimpleActionServer、NodeThread、getCurren","frontmatter":{"title":"规划、控制、恢复都在借谁的手？逐函数拆解 Nav2 公共底座 nav2_util","description":"打开 Planner Server、Controller Server、Costmap、Lifecycle Manager 或 Waypoint Follower 的源码，经常能看到相同的名字：LifecycleNode、SimpleActionServer、NodeThread、getCurren","date":"2026-07-24","topic":"Nav2 工程实践","section":"五 · 平滑器与基础工具","readingTime":31,"source":"2026-07-24/nav2_util_source_walkthrough.md","status":"published","cover":"/article-assets/2026-07-24/nav2_util_source_01_boundary.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-util-source-walkthrough"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"规划、控制、恢复都在借谁的手？逐函数拆解 Nav2 公共底座 nav2_util"}],["meta",{"property":"og:description","content":"打开 Planner Server、Controller Server、Costmap、Lifecycle Manager 或 Waypoint Follower 的源码，经常能看到相同的名字：LifecycleNode、SimpleActionServer、NodeThread、getCurren"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-util-source-walkthrough"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-24/nav2_util_source_01_boundary.png"}],["meta",{"property":"article:published_time","content":"2026-07-24"}],["meta",{"name":"twitter:title","content":"规划、控制、恢复都在借谁的手？逐函数拆解 Nav2 公共底座 nav2_util"}],["meta",{"name":"twitter:description","content":"打开 Planner Server、Controller Server、Costmap、Lifecycle Manager 或 Waypoint Follower 的源码，经常能看到相同的名字：LifecycleNode、SimpleActionServer、NodeThread、getCurren"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-24/nav2_util_source_01_boundary.png"}]],"prev":{"text":"一帧激光如何变成控制器手里的避障地图？拆解 Nav2 局部 Costmap 全数据流","link":"/nav2/nav2-regulated-modules-local-costmap-full-dataflow"},"next":{"text":"控制器只发 20 Hz，底盘为何还能更丝滑？逐函数拆解 Nav2 Velocity Smoother","link":"/nav2/nav2-velocity-smoother-source-walkthrough"}},"headers":[],"relativePath":"nav2/nav2-util-source-walkthrough.md","filePath":"nav2/nav2-util-source-walkthrough.md","lastUpdated":null}'),p={name:"nav2/nav2-util-source-walkthrough.md"};function u(h,e,_,m,g,f){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="规划、控制、恢复都在借谁的手-逐函数拆解-nav2-公共底座-nav2-util" tabindex="-1">规划、控制、恢复都在借谁的手？逐函数拆解 Nav2 公共底座 nav2_util <a class="header-anchor" href="#规划、控制、恢复都在借谁的手-逐函数拆解-nav2-公共底座-nav2-util" aria-label="Permalink to &quot;规划、控制、恢复都在借谁的手？逐函数拆解 Nav2 公共底座 nav2_util&quot;">​</a></h1><p>打开 Planner Server、Controller Server、Costmap、Lifecycle Manager 或 Waypoint Follower 的源码，经常能看到相同的名字：<code>LifecycleNode</code>、<code>SimpleActionServer</code>、<code>NodeThread</code>、<code>getCurrentPose()</code>、<code>declare_parameter_if_not_declared()</code>。</p><p>它们并不是各包自己实现的零散逻辑，而是共同来自 <code>nav2_util</code>。这个包把 ROS 2 原生 Lifecycle、Action、Service、Executor、TF 与消息类型封装成 Nav2 更容易复用的接口。上层节点看起来只调用了一行，背后可能已经完成了独立回调组、工作线程、生命周期心跳、TF 异常分类或时间窗里程计平滑。</p><p>本文基于当前工程中的 <code>nav2_util 1.1.20</code>，覆盖 17 个生产头文件、10 个生产 <code>.cpp</code>、共享库和 <code>lifecycle_bringup</code> 独立命令入口。按具名生产函数、方法、构造／析构和模板入口统计，共 128 个；测试函数、构建宏与匿名 lambda 不计入。对于 rclcpp、rclcpp_action、tf2、bondcpp 等包外调用，本文解释其接口作用与数据流，不展开其他包源码。</p><p><img src="'+r+'" alt="nav2_util 包能力边界与总数据流"></p><h2 id="一、包边界-它不是杂物箱-而是-nav2-的公共适配层" tabindex="-1">一、包边界：它不是杂物箱，而是 Nav2 的公共适配层 <a class="header-anchor" href="#一、包边界-它不是杂物箱-而是-nav2-的公共适配层" aria-label="Permalink to &quot;一、包边界：它不是杂物箱，而是 Nav2 的公共适配层&quot;">​</a></h2><h3 id="_1-1-两个构建产物" tabindex="-1">1.1 两个构建产物 <a class="header-anchor" href="#_1-1-两个构建产物" aria-label="Permalink to &quot;1.1 两个构建产物&quot;">​</a></h3><p><code>src/CMakeLists.txt</code> 把 <code>costmap.cpp</code>、<code>node_utils.cpp</code>、<code>lifecycle_service_client.cpp</code>、<code>string_utils.cpp</code>、<code>lifecycle_utils.cpp</code>、<code>lifecycle_node.cpp</code>、<code>robot_utils.cpp</code>、<code>node_thread.cpp</code> 与 <code>odometry_utils.cpp</code> 编译为共享库 <code>nav2_util_core</code>。</p><p><code>simple_action_server.hpp</code>、<code>service_client.hpp</code>、<code>geometry_utils.hpp</code>、<code>validate_messages.hpp</code> 等模板或内联能力直接放在头文件中，由使用它们的包在编译期实例化。</p><p>包内还构建一个独立程序 <code>lifecycle_bringup</code>。它只负责从命令行接收节点名，依次调用生命周期服务，把节点从 UNCONFIGURED 推到 ACTIVE。</p><h3 id="_1-2-六条能力链" tabindex="-1">1.2 六条能力链 <a class="header-anchor" href="#_1-2-六条能力链" aria-label="Permalink to &quot;1.2 六条能力链&quot;">​</a></h3><p>从输入输出看，<code>nav2_util</code> 可以分成六条数据链：</p><ul><li>生命周期链：状态转换进入 <code>LifecycleNode</code>，资源激活后建立 Bond，ROS Context 关闭前触发清理。</li><li>Action 链：Goal、Cancel、Accepted 回调进入 <code>SimpleActionServer</code>，业务函数在异步线程执行，Result 与 Feedback 返回 Action Client。</li><li>Service 链：Request 进入独立 CallbackGroup，由本地 Executor 等待 Response，超时后移除 pending request。</li><li>空间链：机器人坐标系中的单位位姿进入 TF Buffer，输出全局 Pose 或 tf2 Transform。</li><li>运动链：Odometry 订阅回调维护时间窗累计和，输出平滑 Twist。</li><li>栅格与通用工具链：OccupancyGrid 转换为 Costmap，几何、Bresenham、参数、字符串、计时和消息校验被其他包直接调用。</li></ul><p>这也解释了为什么它被 Planner、Controller、Costmap、Map Server、Behavior Server、AMCL、Waypoint Follower 和 Lifecycle Manager 同时依赖：它提供的不是业务决策，而是这些业务都需要的 ROS 2 接入能力。</p><h2 id="二、lifecyclenode-把-nav2-节点接入统一生命周期" tabindex="-1">二、LifecycleNode：把 Nav2 节点接入统一生命周期 <a class="header-anchor" href="#二、lifecyclenode-把-nav2-节点接入统一生命周期" aria-label="Permalink to &quot;二、LifecycleNode：把 Nav2 节点接入统一生命周期&quot;">​</a></h2><p><img src="'+d+'" alt="Lifecycle、Bond、Service 与预关机数据流"></p><h3 id="_2-1-lifecyclenode-构造阶段做了什么" tabindex="-1">2.1 LifecycleNode()：构造阶段做了什么 <a class="header-anchor" href="#_2-1-lifecyclenode-构造阶段做了什么" aria-label="Permalink to &quot;2.1 LifecycleNode()：构造阶段做了什么&quot;">​</a></h3><p><code>LifecycleNode(node_name, ns, options)</code> 继承包外 <code>rclcpp_lifecycle::LifecycleNode</code>。输入是节点名、命名空间与 NodeOptions，输出是一个具备 ROS 2 生命周期状态机的 Nav2 节点对象。</p><p>构造函数声明并设置 Bond 的 <code>disable_heartbeat_timeout</code> 参数为 true。这里的含义是服务端节点不因为对端心跳超时自行结束；节点存活监测主要由 Lifecycle Manager 一侧负责。</p><p>随后调用 <code>printLifecycleNodeNotification()</code> 输出“等待外部生命周期转换”的日志，并通过 <code>register_rcl_preshutdown_callback()</code> 向当前 rclcpp Context 注册预关机回调。</p><p>构造阶段没有自动 configure 或 activate。状态转换仍由包外 Lifecycle Manager、命令行工具或其他生命周期客户端发起。</p><h3 id="_2-2-lifecyclenode-析构兜底" tabindex="-1">2.2 ~LifecycleNode()：析构兜底 <a class="header-anchor" href="#_2-2-lifecyclenode-析构兜底" aria-label="Permalink to &quot;2.2 ~LifecycleNode()：析构兜底&quot;">​</a></h3><p><code>~LifecycleNode()</code> 先记录销毁日志，再调用 <code>runCleanups()</code>。如果节点仍处于 ACTIVE，它会执行 <code>deactivate()</code>；如果随后处于 INACTIVE，它会执行 <code>cleanup()</code>。</p><p>接着，析构函数从 rclcpp Context 中移除之前注册的 PreShutdown 回调并释放句柄。这样可以避免对象已经销毁后 Context 再回调悬空的 <code>this</code>。</p><p>这条路径是“尽力而为”的兜底，不等于完整生命周期编排。若节点处于其他异常状态，<code>runCleanups()</code> 不会强行遍历所有可能转换。</p><h3 id="_2-3-add-parameter-三个重载" tabindex="-1">2.3 add_parameter() 三个重载 <a class="header-anchor" href="#_2-3-add-parameter-三个重载" aria-label="Permalink to &quot;2.3 add_parameter() 三个重载&quot;">​</a></h3><p>无范围版 <code>add_parameter(name, default_value, description, additional_constraints, read_only)</code> 构造 <code>ParameterDescriptor</code>，填入名称、说明、额外约束文本和只读标志，然后调用包外 <code>declare_parameter()</code>。输入是默认值与元数据，输出是节点参数系统中的已声明参数。</p><p>浮点范围版额外接收 <code>floating_point_range</code>，把 <code>from_value</code>、<code>to_value</code> 与 <code>step</code> 写入 descriptor 的首个 <code>floating_point_range</code>。ROS 2 参数服务会据此描述合法范围。</p><p>整数范围版接收 <code>integer_range</code>，以同样方式填充 <code>integer_range</code>。三个重载都只负责声明，不负责运行期参数回调，也不自动把参数值同步到业务成员。</p><h3 id="_2-4-shared-from-this-与-on-error" tabindex="-1">2.4 shared_from_this() 与 on_error() <a class="header-anchor" href="#_2-4-shared-from-this-与-on-error" aria-label="Permalink to &quot;2.4 shared_from_this() 与 on_error()&quot;">​</a></h3><p><code>shared_from_this()</code> 先调用基类的共享指针接口，再静态转换成 <code>std::shared_ptr&lt;nav2_util::LifecycleNode&gt;</code>。它的输出类型更方便交给需要 Nav2 LifecycleNode 的工具类，例如 Bond 或 OdomSmoother。</p><p><code>on_error(state)</code> 当前不使用输入 State，只输出 FATAL 日志，说明该节点没有实现错误状态处理，然后返回 <code>CallbackReturn::SUCCESS</code>。这个 SUCCESS 不是“故障已经恢复”，只是告诉生命周期状态机该回调执行结束；派生节点若需要真正恢复，必须覆盖此函数。</p><h3 id="_2-5-createbond-与-destroybond" tabindex="-1">2.5 createBond() 与 destroyBond() <a class="header-anchor" href="#_2-5-createbond-与-destroybond" aria-label="Permalink to &quot;2.5 createBond() 与 destroyBond()&quot;">​</a></h3><p><code>createBond()</code> 以 Topic 名 <code>bond</code>、节点名作为 Bond ID、当前 LifecycleNode 共享指针构造包外 <code>bond::Bond</code>。它把心跳周期设为 0.10 秒、超时设为 4.0 秒，然后调用 <code>start()</code>。</p><p>数据流是：节点 ACTIVE 后创建 Bond 对象，bondcpp 周期发布心跳，Lifecycle Manager 订阅并判断节点是否仍存活。</p><p><code>destroyBond()</code> 检查 <code>bond_</code> 是否存在，存在就 reset。对象析构会结束相应的 Bond 通信。它没有向 Lifecycle Manager 发送业务状态，只结束心跳关系。</p><h3 id="_2-6-register-rcl-preshutdown-callback-、on-rcl-preshutdown-与-runcleanups" tabindex="-1">2.6 register_rcl_preshutdown_callback()、on_rcl_preshutdown() 与 runCleanups() <a class="header-anchor" href="#_2-6-register-rcl-preshutdown-callback-、on-rcl-preshutdown-与-runcleanups" aria-label="Permalink to &quot;2.6 register_rcl_preshutdown_callback()、on_rcl_preshutdown() 与 runCleanups()&quot;">​</a></h3><p><code>register_rcl_preshutdown_callback()</code> 从 NodeBaseInterface 取得 rclcpp Context，把 <code>on_rcl_preshutdown()</code> 绑定为 PreShutdown 回调，并保存返回句柄。</p><p>当包外调用 <code>rclcpp::shutdown()</code>，Context 在正式关闭前触发 <code>on_rcl_preshutdown()</code>。该函数先调用 <code>runCleanups()</code>，再调用 <code>destroyBond()</code>。</p><p><code>runCleanups()</code> 根据当前主状态进行有限转换：</p><ul><li>ACTIVE 时调用基类 <code>deactivate()</code>，让派生节点执行停用回调。</li><li>INACTIVE 时调用基类 <code>cleanup()</code>，释放 configure 阶段资源。</li></ul><p>析构和 Context 预关机都复用这段逻辑。两条路径可能先后到达，因此清理函数必须依靠生命周期状态避免重复转换。</p><p><code>printLifecycleNodeNotification()</code> 只负责日志输出，没有输入数据，也不改变状态。</p><h2 id="三、lifecycleserviceclient-与生命周期批处理" tabindex="-1">三、LifecycleServiceClient 与生命周期批处理 <a class="header-anchor" href="#三、lifecycleserviceclient-与生命周期批处理" aria-label="Permalink to &quot;三、LifecycleServiceClient 与生命周期批处理&quot;">​</a></h2><h3 id="_3-1-两个-lifecycleserviceclient-构造函数" tabindex="-1">3.1 两个 LifecycleServiceClient() 构造函数 <a class="header-anchor" href="#_3-1-两个-lifecycleserviceclient-构造函数" aria-label="Permalink to &quot;3.1 两个 LifecycleServiceClient() 构造函数&quot;">​</a></h3><p>单参数构造 <code>LifecycleServiceClient(lifecycle_node_name)</code> 先调用本包 <code>generate_internal_node()</code> 创建一个内部 rclcpp Node，再创建两个 <code>ServiceClient</code>：</p><ul><li><code>&lt;node&gt;/change_state</code>，服务类型是包外 <code>lifecycle_msgs::srv::ChangeState</code>。</li><li><code>&lt;node&gt;/get_state</code>，服务类型是包外 <code>lifecycle_msgs::srv::GetState</code>。</li></ul><p>构造函数以 20 Hz 循环，每次最多等待 2 秒，直到 <code>get_state</code> 服务出现。这一等待没有总超时，只要 ROS 仍运行而目标服务不出现，构造过程就会一直阻塞。</p><p>双参数构造 <code>LifecycleServiceClient(lifecycle_node_name, parent_node)</code> 不创建内部 Node，而是复用调用者提供的 rclcpp Node。其余两个客户端和等待行为相同。</p><h3 id="_3-2-change-state-两个重载的真实返回值" tabindex="-1">3.2 change_state() 两个重载的真实返回值 <a class="header-anchor" href="#_3-2-change-state-两个重载的真实返回值" aria-label="Permalink to &quot;3.2 change_state() 两个重载的真实返回值&quot;">​</a></h3><p>带 timeout 的 <code>change_state(transition, timeout)</code> 先等待 <code>change_state</code> 服务可用，不可用就抛出 <code>runtime_error</code>。随后创建 Request，把输入的 Transition ID 写入 <code>request-&gt;transition.id</code>，调用 <code>ServiceClient::invoke()</code> 并返回 <code>response.get()</code>。</p><p>无 timeout 版 <code>change_state(transition)</code> 固定等待服务 5 秒，创建 Request 与 Response，再调用另一个 <code>invoke()</code> 重载。</p><p>这里有一个容易误读的语义：<code>response.get()</code> 是 shared pointer 的裸指针，不是 <code>ChangeState::Response::success</code> 字段。它转换为 bool 后只说明“取得了非空响应对象”，没有验证目标生命周期节点是否接受了转换。因此调用者不能把 true 直接理解为状态转换成功；严谨代码还应查询 <code>get_state()</code> 或检查 Response 的业务字段。</p><h3 id="_3-3-get-state" tabindex="-1">3.3 get_state() <a class="header-anchor" href="#_3-3-get-state" aria-label="Permalink to &quot;3.3 get_state()&quot;">​</a></h3><p><code>get_state(timeout)</code> 等待 GetState 服务，在超时内不可用就抛异常。服务可用后创建空 Request，通过 <code>invoke()</code> 得到 Response，输出 <code>response-&gt;current_state.id</code>。</p><p>数据流是：目标节点内部状态 → GetState Response → uint8 状态 ID。函数不返回状态标签字符串。</p><h3 id="_3-4-startuplifecyclenode-与-startup-lifecycle-nodes" tabindex="-1">3.4 startupLifecycleNode() 与 startup_lifecycle_nodes() <a class="header-anchor" href="#_3-4-startuplifecyclenode-与-startup-lifecycle-nodes" aria-label="Permalink to &quot;3.4 startupLifecycleNode() 与 startup_lifecycle_nodes()&quot;">​</a></h3><p>内部函数 <code>startupLifecycleNode(node_name, service_call_timeout, retries)</code> 为单个节点创建 LifecycleServiceClient，先请求 CONFIGURE，再请求 ACTIVATE。</p><p>两个调用都包在 <code>RETRY</code> 宏里。宏捕获 <code>runtime_error</code> 后重试；当计数大于 <code>retries</code> 才重新抛出。配置 <code>retries=3</code> 时，实际是一次初始尝试加三次重试，共最多四次。</p><p><code>startup_lifecycle_nodes(vector, timeout, retries)</code> 按 vector 原顺序逐个调用上述内部函数。前一个节点未成功完成前，后一个不会启动。</p><p>字符串重载 <code>startup_lifecycle_nodes(nodes, timeout, retries)</code> 先用本包 <code>split(nodes, &#39;:&#39;)</code> 解析冒号分隔的节点名，再转给 vector 重载。连续冒号会产生空字符串节点名，函数本身不做过滤。</p><h3 id="_3-5-resetlifecyclenode-与-reset-lifecycle-nodes" tabindex="-1">3.5 resetLifecycleNode() 与 reset_lifecycle_nodes() <a class="header-anchor" href="#_3-5-resetlifecyclenode-与-reset-lifecycle-nodes" aria-label="Permalink to &quot;3.5 resetLifecycleNode() 与 reset_lifecycle_nodes()&quot;">​</a></h3><p>内部 <code>resetLifecycleNode()</code> 的结构相同，只是转换序列变为 DEACTIVATE、CLEANUP，目标状态是 UNCONFIGURED。</p><p><code>reset_lifecycle_nodes(vector)</code> 仍按输入顺序执行，并不会自动反转启动顺序。字符串重载同样先 <code>split()</code> 再转发。</p><p>这组函数适合简单批处理，但没有状态自适应：如果目标原本不在 ACTIVE，直接发送 DEACTIVATE 可能失败；源码也没有先调用 <code>get_state()</code> 决定合法转换。</p><h3 id="_3-6-usage-与-main" tabindex="-1">3.6 usage() 与 main() <a class="header-anchor" href="#_3-6-usage-与-main" aria-label="Permalink to &quot;3.6 usage() 与 main()&quot;">​</a></h3><p><code>usage()</code> 向标准错误输出命令格式，然后调用 <code>std::exit(1)</code>。它没有正常返回路径。</p><p><code>main(argc, argv)</code> 在没有节点参数时调用 <code>usage()</code>。有参数时执行 <code>rclcpp::init(0, nullptr)</code>，也就是不把命令行节点列表交给 ROS 参数解析；随后把 <code>argv[1..]</code> 转成字符串 vector，以 10 秒服务调用超时执行 <code>startup_lifecycle_nodes()</code>，最后 <code>rclcpp::shutdown()</code>。函数末尾没有显式 return，C++ 的 <code>main()</code> 会按成功返回 0 处理。</p><h2 id="四、serviceclient-阻塞接口背后的独立回调组" tabindex="-1">四、ServiceClient：阻塞接口背后的独立回调组 <a class="header-anchor" href="#四、serviceclient-阻塞接口背后的独立回调组" aria-label="Permalink to &quot;四、ServiceClient：阻塞接口背后的独立回调组&quot;">​</a></h2><h3 id="_4-1-serviceclient-构造函数" tabindex="-1">4.1 ServiceClient() 构造函数 <a class="header-anchor" href="#_4-1-serviceclient-构造函数" aria-label="Permalink to &quot;4.1 ServiceClient() 构造函数&quot;">​</a></h3><p>模板构造 <code>ServiceClient&lt;ServiceT&gt;(service_name, provided_node)</code> 保存服务名与 Node，创建一个 <code>MutuallyExclusive</code> CallbackGroup，并把自动加入 Executor 设置为 false。</p><p>随后它把这个 CallbackGroup 手动加入成员 <code>SingleThreadedExecutor</code>，再使用包外 <code>node_-&gt;create_client&lt;ServiceT&gt;()</code> 创建 ROS 2 Client。Service QoS 来自 <code>rclcpp::ServicesQoS()</code>。</p><p>这种结构的关键价值是：调用者即使在自己的节点回调里同步等待服务，Response 也可以由这个局部 Executor 处理，不必依赖调用者所在 Executor 再次调度同一个回调。</p><p><img src="'+i+'" alt="内部 Node、参数与通用 ServiceClient 数据流"></p><h3 id="_4-2-invoke-request-timeout" tabindex="-1">4.2 invoke(request, timeout) <a class="header-anchor" href="#_4-2-invoke-request-timeout" aria-label="Permalink to &quot;4.2 invoke(request, timeout)&quot;">​</a></h3><p>返回 Response 的 <code>invoke()</code> 先按 1 秒周期等待服务出现。这里的 <code>timeout</code> 只交给后面的 <code>spin_until_future_complete()</code>，并不限制前置的 wait 循环。服务永远不出现时，只要 <code>rclcpp::ok()</code> 为 true，调用就会继续等。</p><p>服务出现后，函数调用包外 <code>async_send_request()</code> 得到 Future，再由局部 Executor 阻塞等待 Future 完成。</p><p>输出分两类：</p><ul><li>Future 成功完成，返回 <code>future_result.get()</code> 得到的 Response shared pointer。</li><li>超时、中断或其他非 SUCCESS 状态，调用 <code>remove_pending_request()</code> 清理仍登记在 Client 中的请求，然后抛出 <code>runtime_error</code>。</li></ul><p>默认 timeout 是负一纳秒，交给 rclcpp 时代表无限等待。</p><h3 id="_4-3-invoke-request-response" tabindex="-1">4.3 invoke(request, response) <a class="header-anchor" href="#_4-3-invoke-request-response" aria-label="Permalink to &quot;4.3 invoke(request, response)&quot;">​</a></h3><p>另一个 <code>invoke()</code> 把 Response 作为输出引用，前置服务等待和异步请求相同，但 <code>spin_until_future_complete()</code> 不传 timeout。</p><p>非 SUCCESS 时移除 pending request 并返回 false；成功时把 Response shared pointer 写入输出引用，最后返回 <code>response.get()</code> 转换得到的 bool。这个 bool 仍只代表指针是否非空，不代表服务响应中的业务成功字段。</p><h3 id="_4-4-wait-for-service-与-getservicename" tabindex="-1">4.4 wait_for_service() 与 getServiceName() <a class="header-anchor" href="#_4-4-wait-for-service-与-getservicename" aria-label="Permalink to &quot;4.4 wait_for_service() 与 getServiceName()&quot;">​</a></h3><p><code>wait_for_service(timeout)</code> 原样转发到包外 rclcpp Client，输出服务是否在时限内可用。</p><p><code>getServiceName()</code> 返回构造时保存的名称，不向 ROS Graph 重新查询。</p><h3 id="_4-5-clearentirelycostmapserviceclient" tabindex="-1">4.5 ClearEntirelyCostmapServiceClient() <a class="header-anchor" href="#_4-5-clearentirelycostmapserviceclient" aria-label="Permalink to &quot;4.5 ClearEntirelyCostmapServiceClient()&quot;">​</a></h3><p><code>ClearEntirelyCostmapServiceClient(service_name)</code> 是 <code>ServiceClient&lt;nav2_msgs::srv::ClearEntireCostmap&gt;</code> 的薄派生构造，只把服务名传给基类。它不增加调用逻辑，只为清空整张 Costmap 的 Request、Response 类型和用途提供更明确的类型名。</p><p>但当前本地 <code>ServiceClient</code> 只定义了“服务名＋Node”的双参数构造，没有单参数构造。这个派生构造的基类初始化因此不匹配；现有共享库没有包含该头文件，所以常规目标可能不暴露问题，一旦其他代码直接包含它就会编译失败。它是当前版本中保留但不可直接使用的接口。</p><h2 id="五、simpleactionserver-一个-current、一个-pending、一条工作线程" tabindex="-1">五、SimpleActionServer：一个 current、一个 pending、一条工作线程 <a class="header-anchor" href="#五、simpleactionserver-一个-current、一个-pending、一条工作线程" aria-label="Permalink to &quot;五、SimpleActionServer：一个 current、一个 pending、一条工作线程&quot;">​</a></h2><p><img src="'+n+'" alt="SimpleActionServer Goal、抢占、取消与终态"></p><h3 id="_5-1-两个-simpleactionserver-构造函数" tabindex="-1">5.1 两个 SimpleActionServer() 构造函数 <a class="header-anchor" href="#_5-1-两个-simpleactionserver-构造函数" aria-label="Permalink to &quot;5.1 两个 SimpleActionServer() 构造函数&quot;">​</a></h3><p>模板构造接收 Node 对象，提取 NodeBase、NodeClock、NodeLogging 和 NodeWaitables 四个包外接口，然后委托给完整构造函数。输入还包括 Action 名、业务 <code>execute_callback</code>、可选 <code>completion_callback</code>、停用等待时限、是否使用独立 spin 线程以及底层 Action Server options。</p><p>完整构造保存这些接口与回调，通过包外 <code>rclcpp_action::create_server&lt;ActionT&gt;()</code> 注册三个回调：</p><ul><li>Goal 请求绑定到 <code>handle_goal()</code>。</li><li>Cancel 请求绑定到 <code>handle_cancel()</code>。</li><li>已接受 Goal 绑定到 <code>handle_accepted()</code>。</li></ul><p>如果 <code>spin_thread=true</code>，构造函数创建不自动加入主 Executor 的 MutuallyExclusive CallbackGroup，再创建 SingleThreadedExecutor 和 <code>NodeThread</code>。Action 请求回调由这条独立 spin 线程处理。</p><p>如果 <code>spin_thread=false</code>，CallbackGroup 为空，Action Server 使用节点默认执行关系，由外部 Executor 驱动。</p><h3 id="_5-2-handle-goal" tabindex="-1">5.2 handle_goal() <a class="header-anchor" href="#_5-2-handle-goal" aria-label="Permalink to &quot;5.2 handle_goal()&quot;">​</a></h3><p><code>handle_goal(uuid, goal)</code> 持有递归互斥锁，但当前实现不读取 UUID 和 Goal 内容。</p><p><code>server_active_</code> 为 false 时输出 <code>GoalResponse::REJECT</code>；为 true 时固定输出 <code>ACCEPT_AND_EXECUTE</code>。因此目标格式、坐标合法性、插件是否存在等业务校验不在这里完成，必须由 execute callback 负责。</p><h3 id="_5-3-handle-cancel" tabindex="-1">5.3 handle_cancel() <a class="header-anchor" href="#_5-3-handle-cancel" aria-label="Permalink to &quot;5.3 handle_cancel()&quot;">​</a></h3><p><code>handle_cancel(handle)</code> 同样持锁。若 GoalHandle 已不 active，返回 REJECT；否则固定返回 ACCEPT。</p><p>ACCEPT 只会把 GoalHandle 推入 canceling 状态，不会自动停止业务循环。execute callback 必须周期调用 <code>is_cancel_requested()</code>，再调用 <code>terminate_current()</code> 或 <code>terminate_all()</code>，才能真正给客户端发送 canceled Result。</p><h3 id="_5-4-handle-accepted" tabindex="-1">5.4 handle_accepted() <a class="header-anchor" href="#_5-4-handle-accepted" aria-label="Permalink to &quot;5.4 handle_accepted()&quot;">​</a></h3><p>当 Action 框架接受 Goal 后，<code>handle_accepted(handle)</code> 决定它进入 current 还是 pending。</p><p>若当前 Goal 仍 active，或异步执行 Future 仍在运行，新 Goal 被放进唯一的 <code>pending_handle_</code>，并设置 <code>preempt_requested_=true</code>。如果 pending 槽已经有 active Goal，旧 pending 会先被 <code>terminate()</code>，然后被最新 Goal 替换。</p><p>若当前没有任务，输入 handle 成为 <code>current_handle_</code>，函数通过 <code>std::async(std::launch::async)</code> 启动 <code>work()</code>。这样 Accepted 回调可以快速返回，不阻塞 ROS Executor。</p><p>源码只保留一个 pending 槽，所以连续抢占不是排队执行，而是“最新目标覆盖旧待执行目标”。</p><h3 id="_5-5-work" tabindex="-1">5.5 work() <a class="header-anchor" href="#_5-5-work" aria-label="Permalink to &quot;5.5 work()&quot;">​</a></h3><p><code>work()</code> 的循环条件是 ROS 正常、没有 stop request、当前 Goal active。每轮先调用用户提供的 <code>execute_callback_()</code>。</p><p>这个回调没有 Goal 参数。业务代码要通过 <code>get_current_goal()</code> 获取输入，通过 <code>publish_feedback()</code> 输出反馈，通过 <code>succeeded_current()</code>、<code>terminate_current()</code> 等接口设置终态，同时自己检查 cancel 与 preempt。</p><p>如果 execute callback 抛出 <code>std::exception</code>，<code>work()</code> 记录错误，终止 current 与 pending，然后调用 CompletionCallback 并返回。</p><p>回调正常返回后，工作线程持锁检查：</p><ul><li><code>stop_execution_</code> 为 true：终止全部 Goal，调用 CompletionCallback，结束循环。</li><li>当前 Goal 仍 active：说明业务回调忘记设置终态，服务器会 abort 当前 Goal并调用 CompletionCallback。</li><li>pending Goal active：调用 <code>accept_pending_goal()</code>，沿用现有工作线程进入下一轮。</li><li>没有 pending：工作线程结束。</li></ul><p>CompletionCallback 默认可以为空，但上述异常、stop 和“未完成 Goal”分支中存在无条件调用。这意味着调用者若不提供 CompletionCallback，又触发这些分支，可能抛出 <code>std::bad_function_call</code>。业务代码不能依赖默认空回调处理失败路径。</p><h3 id="_5-6-activate-、deactivate-与-is-running" tabindex="-1">5.6 activate()、deactivate() 与 is_running() <a class="header-anchor" href="#_5-6-activate-、deactivate-与-is-running" aria-label="Permalink to &quot;5.6 activate()、deactivate() 与 is_running()&quot;">​</a></h3><p><code>activate()</code> 持锁把 <code>server_active_</code> 设为 true，并清除 <code>stop_execution_</code>。它不创建底层 Action Server，因为服务器已在构造阶段建立；这里只打开 Goal 接收门。</p><p><code>deactivate()</code> 先把 <code>server_active_</code> 设为 false、<code>stop_execution_</code> 设为 true。没有执行 Future 时立即返回；Future 仍运行时，每 100 毫秒检查一次。</p><p>等待超过 <code>server_timeout_</code> 后，函数会 <code>terminate_all()</code>，有 CompletionCallback 才调用，并输出超时错误。但源码没有 break 或 return，仍会继续等待 execute callback 自己结束。因此 <code>server_timeout_</code> 不是强制杀线程时限，只是触发 Goal 终止和错误日志的阈值。</p><p><code>is_running()</code> 检查 Future 是否有效，并用零时长 wait 判断其状态。返回 true 只说明异步任务尚未 ready，不保证 <code>current_handle_</code> 仍 active。</p><p><code>is_server_active()</code> 持锁读取接收门状态。</p><h3 id="_5-7-抢占相关接口" tabindex="-1">5.7 抢占相关接口 <a class="header-anchor" href="#_5-7-抢占相关接口" aria-label="Permalink to &quot;5.7 抢占相关接口&quot;">​</a></h3><p><code>is_preempt_requested()</code> 持锁返回 <code>preempt_requested_</code>。业务回调看到 true 后，可以决定何时安全切换。</p><p><code>accept_pending_goal()</code> 要求 pending 存在且 active，否则输出错误并返回空 Goal 指针。若 current 仍 active 且不是同一 Handle，它直接对 current 调用 <code>abort(empty_result())</code>。随后把 pending 移到 current，清空 pending 和抢占标志，输出新 Goal 对象。</p><p>这条切换路径对旧 current 固定使用 abort，不会因为旧 Goal 正在 canceling 而改发 canceled。</p><p><code>terminate_pending_goal()</code> 检查 pending 后调用通用 <code>terminate()</code>，清除抢占标志。<code>terminate()</code> 会根据 GoalHandle 是否 canceling 选择 canceled 或 abort。</p><p><code>get_pending_goal()</code> 返回 pending Goal 内容；不存在或不 active 时输出错误并返回空指针。</p><h3 id="_5-8-当前-goal、取消与输出接口" tabindex="-1">5.8 当前 Goal、取消与输出接口 <a class="header-anchor" href="#_5-8-当前-goal、取消与输出接口" aria-label="Permalink to &quot;5.8 当前 Goal、取消与输出接口&quot;">​</a></h3><p><code>get_current_goal()</code> 持锁检查 current active，成功时输出 <code>ActionT::Goal</code> 的 const shared pointer，失败时返回空。</p><p><code>get_current_goal_id()</code> 返回 Goal UUID；没有 active current 时返回全零默认 UUID。</p><p><code>is_cancel_requested()</code> 在 current 为空时返回 false。如果 pending 非空，它只返回 pending 的 <code>is_canceling()</code>；否则读取 current。</p><p>这与注释中“任一 Handle 取消都算取消”并不完全一致：当 pending 存在时，current 的取消状态会被 pending 分支遮蔽。业务回调在“当前目标被取消，同时有待抢占目标”的组合场景中需要特别谨慎。</p><p><code>publish_feedback(feedback)</code> 检查 current active 后调用包外 GoalHandle 的 <code>publish_feedback()</code>。它没有像其他 Handle 操作一样持有 <code>update_mutex_</code>，与并发终止或切换目标之间存在调用时序边界。</p><h3 id="_5-9-终态接口" tabindex="-1">5.9 终态接口 <a class="header-anchor" href="#_5-9-终态接口" aria-label="Permalink to &quot;5.9 终态接口&quot;">​</a></h3><p><code>terminate_all(result)</code> 持锁，对 current 和 pending 分别调用 <code>terminate()</code>，然后清除抢占标志。</p><p><code>terminate_current(result)</code> 只终止 current。</p><p><code>succeeded_current(result)</code> 在 current active 时调用包外 <code>GoalHandle::succeed()</code>，然后 reset current。它不处理 pending；工作线程回到 <code>work()</code> 后会检测并切换 pending。</p><p><code>terminate(handle, result)</code> 是统一终止函数：Handle active 且 canceling 时调用 <code>canceled()</code>，否则调用 <code>abort()</code>，最后 reset Handle。</p><p><code>empty_result()</code> 构造默认的 <code>ActionT::Result</code> shared pointer，供旧 Goal abort 等路径使用。</p><p><code>is_active(handle)</code> 输出“指针非空且 GoalHandle active”的组合判断。</p><h3 id="_5-10-四个日志函数" tabindex="-1">5.10 四个日志函数 <a class="header-anchor" href="#_5-10-四个日志函数" aria-label="Permalink to &quot;5.10 四个日志函数&quot;">​</a></h3><p><code>info_msg()</code>、<code>debug_msg()</code>、<code>error_msg()</code>、<code>warn_msg()</code> 分别调用包外 RCLCPP_INFO、DEBUG、ERROR、WARN。它们统一在日志前增加 Action 名和 <code>[ActionServer]</code> 标记，不改变服务器状态。</p><p>这 28 个方法共同组成的关键约束是：SimpleActionServer 负责线程、Handle 和终态通道，具体业务回调仍负责主动检查 cancel／preempt、生成 Result、发布 Feedback 和及时返回。</p><h2 id="六、nodethread-与内部-node-谁来执行回调" tabindex="-1">六、NodeThread 与内部 Node：谁来执行回调 <a class="header-anchor" href="#六、nodethread-与内部-node-谁来执行回调" aria-label="Permalink to &quot;六、NodeThread 与内部 Node：谁来执行回调&quot;">​</a></h2><h3 id="_6-1-nodethread-nodebaseinterface" tabindex="-1">6.1 NodeThread(NodeBaseInterface) <a class="header-anchor" href="#_6-1-nodethread-nodebaseinterface" aria-label="Permalink to &quot;6.1 NodeThread(NodeBaseInterface)&quot;">​</a></h3><p><code>NodeThread(node_base)</code> 保存 NodeBaseInterface，创建包外 <code>SingleThreadedExecutor</code>，然后启动 <code>std::thread</code>。</p><p>线程函数依次执行 <code>executor_-&gt;add_node(node_)</code>、<code>spin()</code>、<code>remove_node(node_)</code>。输入是一个节点接口，输出不是业务数据，而是一条持续处理该节点 Timer、Subscription、Service、Action 等回调的后台执行流。</p><h3 id="_6-2-nodethread-singlethreadedexecutor" tabindex="-1">6.2 NodeThread(SingleThreadedExecutor) <a class="header-anchor" href="#_6-2-nodethread-singlethreadedexecutor" aria-label="Permalink to &quot;6.2 NodeThread(SingleThreadedExecutor)&quot;">​</a></h3><p>另一个构造直接接收已经配置好的 Executor，启动线程调用 <code>executor_-&gt;spin()</code>。SimpleActionServer 使用的就是这一版，因为它只想执行手动加入 Executor 的独立 CallbackGroup。</p><h3 id="_6-3-nodethread-nodet-模板构造" tabindex="-1">6.3 NodeThread(NodeT) 模板构造 <a class="header-anchor" href="#_6-3-nodethread-nodet-模板构造" aria-label="Permalink to &quot;6.3 NodeThread(NodeT) 模板构造&quot;">​</a></h3><p>模板构造接收任意提供 <code>get_node_base_interface()</code> 的 Node 指针，提取接口后委托给首个构造函数。它只是调用便利层。</p><h3 id="_6-4-nodethread" tabindex="-1">6.4 ~NodeThread() <a class="header-anchor" href="#_6-4-nodethread" aria-label="Permalink to &quot;6.4 ~NodeThread()&quot;">​</a></h3><p>析构函数调用包外 <code>Executor::cancel()</code> 让 spin 返回，再 <code>join()</code> 等待后台线程结束。</p><p>调用者必须保证析构发生在其他线程；若在被 join 的同一执行线程中销毁对象，会触发自等待问题。源码没有 detach 或自线程检测。</p><h3 id="_6-5-sanitize-node-name-与-time-to-string" tabindex="-1">6.5 sanitize_node_name() 与 time_to_string() <a class="header-anchor" href="#_6-5-sanitize-node-name-与-time-to-string" aria-label="Permalink to &quot;6.5 sanitize_node_name() 与 time_to_string()&quot;">​</a></h3><p><code>sanitize_node_name(potential_node_name)</code> 复制输入，把所有非字母数字字符替换为 <code>_</code>，输出 ROS 节点名候选。它不单独处理空字符串，也不验证替换后的首字符是否满足所有 ROS 命名约束。</p><p><code>time_to_string(len)</code> 读取 <code>high_resolution_clock</code> 距 epoch 的计数，取末尾 len 位；位数不足时左侧补零。它提供时间相关后缀，不是随机数生成器，也不保证高并发创建时绝对无碰撞。</p><h3 id="_6-6-generate-internal-node-name-与-generate-internal-node" tabindex="-1">6.6 generate_internal_node_name() 与 generate_internal_node() <a class="header-anchor" href="#_6-6-generate-internal-node-name-与-generate-internal-node" aria-label="Permalink to &quot;6.6 generate_internal_node_name() 与 generate_internal_node()&quot;">​</a></h3><p><code>generate_internal_node_name(prefix)</code> 把 sanitize 后的前缀、下划线和 8 位时间后缀拼接成节点名。</p><p><code>generate_internal_node(prefix)</code> 构造 NodeOptions，关闭参数服务和参数事件 Publisher，通过 ROS 参数重映射把真实节点名设为上述生成结果，再以占位名 <code>_</code> 调用 <code>rclcpp::Node::make_shared()</code>。</p><p>输出 Node 适合工具客户端内部使用：它能创建 Service Client，却不会额外暴露完整参数服务，减少 ROS Graph 噪声。</p><h3 id="_6-7-add-namespaces" tabindex="-1">6.7 add_namespaces() <a class="header-anchor" href="#_6-7-add-namespaces" aria-label="Permalink to &quot;6.7 add_namespaces()&quot;">​</a></h3><p><code>add_namespaces(top_ns, sub_ns)</code> 拼接命名空间。如果 top 以 <code>/</code> 结尾但不以 <code>/</code> 开头，函数会主动补前导斜杠；如果 top 已以 <code>/</code> 开头则直接拼接。</p><p>如果 top 不以 <code>/</code> 结尾，源码直接返回 <code>top_ns + &quot;/&quot; + sub_ns</code>。因此 <code>top_ns=&quot;robot&quot;</code> 时输出 <code>robot/sub</code>，并不保证头文件注释所说的“绝对命名空间”。空 top 则得到 <code>/sub</code>。</p><h3 id="_6-8-两个-declare-parameter-if-not-declared" tabindex="-1">6.8 两个 declare_parameter_if_not_declared() <a class="header-anchor" href="#_6-8-两个-declare-parameter-if-not-declared" aria-label="Permalink to &quot;6.8 两个 declare_parameter_if_not_declared()&quot;">​</a></h3><p>默认值版模板先调用包外 <code>has_parameter()</code>。参数不存在时，用给定 ParameterValue 和 descriptor 声明；已存在时不读取、不覆盖。</p><p>类型版模板把默认值换成 ParameterType，适合声明一个必须由配置提供、暂时未初始化的参数。</p><p>这两个函数的输出体现在 Node 参数存储中，没有返回值。它们避免插件和主节点重复声明同名参数，但不会检查已有参数的类型是否符合当前调用者预期。</p><h3 id="_6-9-get-plugin-type-param" tabindex="-1">6.9 get_plugin_type_param() <a class="header-anchor" href="#_6-9-get-plugin-type-param" aria-label="Permalink to &quot;6.9 get_plugin_type_param()&quot;">​</a></h3><p><code>get_plugin_type_param(node, plugin_name)</code> 构造 <code>&lt;plugin_name&gt;.plugin</code>，先用类型版声明为 string，再调用包外 <code>get_parameter()</code>。</p><p>成功输出插件类型字符串。读取返回 false 或抛出 <code>ParameterUninitializedException</code> 时，它记录 FATAL 并直接 <code>exit(-1)</code>。这是进程级失败，而不是可以由 configure 回调捕获并转成 Lifecycle FAILURE 的普通异常。</p><h3 id="_6-10-copy-all-parameters" tabindex="-1">6.10 copy_all_parameters() <a class="header-anchor" href="#_6-10-copy-all-parameters" aria-label="Permalink to &quot;6.10 copy_all_parameters()&quot;">​</a></h3><p><code>copy_all_parameters(parent, child)</code> 调用包外 <code>list_parameters({}, 0)</code> 获取父节点所有参数名，再批量 <code>get_parameters()</code>。</p><p>循环中只把 child 尚未声明的参数，以当前值声明到 child。已存在参数不会覆盖；descriptor、只读属性和范围等元数据也不会复制，只复制 ParameterValue。</p><h2 id="七、robot-utils-从-tf-得到机器人位姿和变换" tabindex="-1">七、robot_utils：从 TF 得到机器人位姿和变换 <a class="header-anchor" href="#七、robot-utils-从-tf-得到机器人位姿和变换" aria-label="Permalink to &quot;七、robot_utils：从 TF 得到机器人位姿和变换&quot;">​</a></h2><p><img src="'+l+'" alt="TF、位姿、几何与栅格工具链"></p><h3 id="_7-1-getcurrentpose" tabindex="-1">7.1 getCurrentPose() <a class="header-anchor" href="#_7-1-getcurrentpose" aria-label="Permalink to &quot;7.1 getCurrentPose()&quot;">​</a></h3><p><code>getCurrentPose(global_pose, tf_buffer, global_frame, robot_frame, timeout, stamp)</code> 先在 <code>robot_frame</code> 中构造一个单位 Pose：位置为原点，姿态为单位旋转，时间戳使用输入 stamp。</p><p>随后它把同一个 <code>global_pose</code> 同时作为 <code>transformPoseInTargetFrame()</code> 的输入与输出。包外 TF Buffer 将“机器人坐标系原点”变换到 global frame，结果就是机器人在全局坐标系中的当前位姿。</p><p>输出 bool 表示变换是否成功；真正 Pose 写入引用参数。默认 stamp 为零时间，通常表示取 TF Buffer 中最新可用变换。</p><h3 id="_7-2-transformposeintargetframe" tabindex="-1">7.2 transformPoseInTargetFrame() <a class="header-anchor" href="#_7-2-transformposeintargetframe" aria-label="Permalink to &quot;7.2 transformPoseInTargetFrame()&quot;">​</a></h3><p>输入是 PoseStamped、目标 frame、TF Buffer 与超时。函数调用包外 <code>tf_buffer.transform()</code>，成功时写出 transformed Pose 并返回 true。</p><p>它分别捕获 Lookup、Connectivity、Extrapolation、Timeout 和通用 TransformException，输出不同错误日志后返回 false。函数不重试，也不修改调用者的 TF Buffer。</p><h3 id="_7-3-gettransform-最新变换重载" tabindex="-1">7.3 getTransform() 最新变换重载 <a class="header-anchor" href="#_7-3-gettransform-最新变换重载" aria-label="Permalink to &quot;7.3 getTransform() 最新变换重载&quot;">​</a></h3><p>四个主要输入是 source frame、target frame、容忍时间和 shared TF Buffer，输出写入 <code>tf2::Transform</code> 引用。</p><p>函数先把输出设为单位变换。source 与 target 相同则直接返回 true。否则调用包外 <code>lookupTransform(target, source, TimePointZero, tolerance)</code> 获取最新变换，再用 <code>tf2::fromMsg()</code> 转换消息类型。</p><p>任何 TransformException 都返回 false，且输出仍保持调用前设置的单位变换。调用者必须检查 bool，不能把单位变换误当成真实查询结果。</p><h3 id="_7-4-gettransform-跨时间重载" tabindex="-1">7.4 getTransform() 跨时间重载 <a class="header-anchor" href="#_7-4-gettransform-跨时间重载" aria-label="Permalink to &quot;7.4 getTransform() 跨时间重载&quot;">​</a></h3><p>跨时间版额外接收 source time、target time 与 fixed frame。它调用 tf2 的高级查询：在 fixed frame 中考虑两个时间点，计算 source 在 source time 到 target 在 target time 的变换。</p><p>这适合传感器数据时间对齐。与最新变换版不同，它没有 source frame 等于 target frame 的快速返回，因为不同时间上的同名坐标系仍可能产生有效运动变换。</p><h3 id="_7-5-validatetwist" tabindex="-1">7.5 validateTwist() <a class="header-anchor" href="#_7-5-validatetwist" aria-label="Permalink to &quot;7.5 validateTwist()&quot;">​</a></h3><p><code>validateTwist(msg)</code> 逐项检查 linear x／y／z 与 angular x／y／z。任一分量是 NaN 或 Inf 就返回 false，全部有限才返回 true。</p><p>它不检查速度范围、底盘自由度、时间戳或 frame，因为普通 Twist 本身没有 Header。速度上下限仍由 Controller、Velocity Smoother 或底盘层负责。</p><h2 id="八、odomsmoother-按时间窗维护-twist-均值" tabindex="-1">八、OdomSmoother：按时间窗维护 Twist 均值 <a class="header-anchor" href="#八、odomsmoother-按时间窗维护-twist-均值" aria-label="Permalink to &quot;八、OdomSmoother：按时间窗维护 Twist 均值&quot;">​</a></h2><p><img src="'+s+'" alt="Odometry 时间窗平滑与消息校验"></p><h3 id="_8-1-两个-odomsmoother-构造函数" tabindex="-1">8.1 两个 OdomSmoother() 构造函数 <a class="header-anchor" href="#_8-1-两个-odomsmoother-构造函数" aria-label="Permalink to &quot;8.1 两个 OdomSmoother() 构造函数&quot;">​</a></h3><p>两个构造分别接收 <code>rclcpp::Node::WeakPtr</code> 和 <code>nav2_util::LifecycleNode::WeakPtr</code>，其余输入都是 filter duration 与 odom Topic。</p><p>它们把 double 秒转换为 <code>rclcpp::Duration</code>，lock WeakPtr 后调用包外 <code>create_subscription&lt;nav_msgs::msg::Odometry&gt;()</code>。QoS 使用 SystemDefaults，回调绑定 <code>odomCallback()</code>。</p><p>随后把 <code>odom_cumulate_.twist.twist</code> 的六个分量清零。</p><p>两个构造实现几乎相同，只为普通 Node 与 LifecycleNode 提供类型兼容。源码没有检查 WeakPtr lock 是否得到有效节点；父节点已经销毁时，随后解引用会失败。</p><h3 id="_8-2-odomcallback" tabindex="-1">8.2 odomCallback() <a class="header-anchor" href="#_8-2-odomcallback" aria-label="Permalink to &quot;8.2 odomCallback()&quot;">​</a></h3><p>订阅输入是 Odometry shared pointer。回调先持有 <code>odom_mutex_</code>。</p><p>历史非空时，它用新消息 header stamp 作为 current time，队首 stamp 作为 front time。只要二者差值大于时间窗，就从累计和中减去队首 Twist 六分量，并 pop_front，直到队列为空或最老样本仍在窗口内。</p><p>然后把新消息复制进 deque，调用 <code>updateState()</code>。</p><p>这里的窗口由消息时间戳决定，不是回调实际到达时间。时间戳回跳时 <code>current-front</code> 变成负值，旧样本不会按预期淘汰，历史队列可能持续增长。</p><h3 id="_8-3-updatestate" tabindex="-1">8.3 updateState() <a class="header-anchor" href="#_8-3-updatestate" aria-label="Permalink to &quot;8.3 updateState()&quot;">​</a></h3><p><code>updateState()</code> 取队尾最新 Odometry，把六个 Twist 分量加入累计和。</p><p>再把最新 Odometry Header 复制给 <code>vel_smooth_</code>，每个累计分量除以当前历史样本数，得到简单算术平均。</p><p>因此输出 Header 对应最新样本，但速度值代表整个时间窗均值；它不是加权滤波，也没有使用 Pose 或协方差。</p><h3 id="_8-4-gettwist-与-gettwiststamped" tabindex="-1">8.4 getTwist() 与 getTwistStamped() <a class="header-anchor" href="#_8-4-gettwist-与-gettwiststamped" aria-label="Permalink to &quot;8.4 getTwist() 与 getTwistStamped()&quot;">​</a></h3><p><code>getTwist()</code> 返回 <code>vel_smooth_.twist</code> 的值拷贝；<code>getTwistStamped()</code> 返回包含最新 Header 的完整值拷贝。</p><p>两个读取函数没有持有 <code>odom_mutex_</code>。如果它们与订阅回调由不同线程同时执行，读写 <code>vel_smooth_</code> 存在同步边界。典型调用若使用单线程 Executor 可能不暴露问题，但类接口本身没有保证线程安全读取。</p><h2 id="九、costmap-从-occupancygrid-到-nav2-cost-值" tabindex="-1">九、Costmap：从 OccupancyGrid 到 Nav2 Cost 值 <a class="header-anchor" href="#九、costmap-从-occupancygrid-到-nav2-cost-值" aria-label="Permalink to &quot;九、Costmap：从 OccupancyGrid 到 Nav2 Cost 值&quot;">​</a></h2><h3 id="_9-1-costmap-与-costmap" tabindex="-1">9.1 Costmap() 与 ~Costmap() <a class="header-anchor" href="#_9-1-costmap-与-costmap" aria-label="Permalink to &quot;9.1 Costmap() 与 ~Costmap()&quot;">​</a></h3><p>构造函数接收裸 Node 指针、是否使用三值代价图、是否跟踪未知空间、致命阈值和未知值。它保存这些配置，阈值不在 0～100 时只输出警告，不做 clamp。</p><p>Node 是裸指针，调用者必须保证它比 Costmap 活得更久。</p><p>析构函数为空。</p><p>当前构造初始化列表没有初始化 <code>map_provided_</code> 与 <code>using_test_map_</code>。后续 <code>get_costmap()</code> 在地图尚未设置时读取这两个 bool，存在未定义行为风险，这是不能忽略的源码边界。</p><h3 id="_9-2-set-static-map" tabindex="-1">9.2 set_static_map() <a class="header-anchor" href="#_9-2-set-static-map" aria-label="Permalink to &quot;9.2 set_static_map()&quot;">​</a></h3><p>输入是包外 <code>nav_msgs::msg::OccupancyGrid</code>。</p><p>函数用节点当前时间填写 map load time 与 update time，layer 写为 <code>Master</code>，再复制 resolution、width、height 与 origin。</p><p><code>costs_</code> resize 为 width×height，然后按行遍历输入 data，对每个 int8 栅格调用 <code>interpret_value()</code>，输出 uint8 Nav2 cost。</p><p>函数最后把 <code>map_provided_</code> 设为 true。它没有先验证 <code>data.size()==width×height</code>，数据过短时会越界读取；严谨调用者应先使用消息校验。</p><h3 id="_9-3-interpret-value" tabindex="-1">9.3 interpret_value() <a class="header-anchor" href="#_9-3-interpret-value" aria-label="Permalink to &quot;9.3 interpret_value()&quot;">​</a></h3><p>输入是 OccupancyGrid 单元值，输出规则如下：</p><ul><li>跟踪未知空间且 value 等于 unknown cost，输出 255，即 <code>no_information</code>。</li><li>不跟踪未知空间但 value 是 unknown，输出 0，即 <code>free_space</code>。</li><li>value 大于等于 lethal threshold，输出 254，即 <code>lethal_obstacle</code>。</li><li>三值模式下，其余值都输出 0。</li><li>非三值模式下，理论上应按 value／threshold 缩放到 0～254。</li></ul><p>当前非三值实现先计算 <code>value / lethal_threshold_</code>，两个操作数都是整数，结果再转 double。低于阈值的正值会先截成 0，导致几乎都映射为 free space。若目标是连续代价，这里的转换顺序需要调用者特别核对。</p><h3 id="_9-4-set-test-costmap-与-get-test-data" tabindex="-1">9.4 set_test_costmap() 与 get_test_data() <a class="header-anchor" href="#_9-4-set-test-costmap-与-get-test-data" aria-label="Permalink to &quot;9.4 set_test_costmap() 与 get_test_data()&quot;">​</a></h3><p><code>set_test_costmap(type)</code> 创建固定 10×10、分辨率 1、原点零位姿的测试 Costmap，方向通过本包 <code>orientationAroundZAxis(0)</code> 生成。</p><p><code>get_test_data(configuration)</code> 根据枚举返回六组硬编码 uint8 数组：全空、未知边界、左下障碍、左上障碍、Maze 1 与 Maze 2。默认分支回到全空地图。</p><p>输出 costs 写入成员，并把 <code>using_test_map_</code> 设为 true。这些地图主要用于规划与单元测试，不包含真实 Static Layer 的膨胀和多层融合。</p><h3 id="_9-5-get-costmap-与-get-properties" tabindex="-1">9.5 get_costmap() 与 get_properties() <a class="header-anchor" href="#_9-5-get-costmap-与-get-properties" aria-label="Permalink to &quot;9.5 get_costmap() 与 get_properties()&quot;">​</a></h3><p><code>get_costmap(specifications)</code> 在两个来源标志都为 false 时抛异常。当前实现忽略输入 specifications，直接用内部已有元数据和 costs 构造 <code>nav2_msgs::msg::Costmap</code>。</p><p>输出 Header 时间为节点当前时间，frame 固定写成 <code>map</code>。即使输入 OccupancyGrid Header 使用其他 frame，这里也不会继承。</p><p><code>get_properties()</code> 直接按值返回内部 <code>CostmapMetaData</code>。</p><h3 id="_9-6-is-free-两个重载" tabindex="-1">9.6 is_free() 两个重载 <a class="header-anchor" href="#_9-6-is-free-两个重载" aria-label="Permalink to &quot;9.6 is_free() 两个重载&quot;">​</a></h3><p>坐标版 <code>is_free(x, y)</code> 用 <code>y*size_x+x</code> 计算一维 index，再转给索引版。</p><p>索引版检查 <code>costs_[index] &lt; inscribed_inflated_obstacle</code>。0、128 等低于 253 的值视为 free；253、254、255 视为不可通行。</p><p>两个重载都不检查坐标或 index 边界。它们也把中等代价当作“free”，所以这个 bool 只表达是否低于 inscribed threshold，不表达路径代价是否理想。</p><h3 id="_9-7-occ-grid-常量" tabindex="-1">9.7 OCC_GRID 常量 <a class="header-anchor" href="#_9-7-occ-grid-常量" aria-label="Permalink to &quot;9.7 OCC_GRID 常量&quot;">​</a></h3><p><code>occ_grid_values.hpp</code> 没有函数，只定义 <code>OCC_GRID_UNKNOWN=-1</code>、<code>OCC_GRID_FREE=0</code>、<code>OCC_GRID_OCCUPIED=100</code>。它们属于 OccupancyGrid 语义，与 Costmap 内部的 0、253、254、255 不是同一数值体系。</p><h2 id="十、geometry-utils-与-lineiterator-路径和栅格的基础数学" tabindex="-1">十、geometry_utils 与 LineIterator：路径和栅格的基础数学 <a class="header-anchor" href="#十、geometry-utils-与-lineiterator-路径和栅格的基础数学" aria-label="Permalink to &quot;十、geometry_utils 与 LineIterator：路径和栅格的基础数学&quot;">​</a></h2><h3 id="_10-1-orientationaroundzaxis" tabindex="-1">10.1 orientationAroundZAxis() <a class="header-anchor" href="#_10-1-orientationaroundzaxis" aria-label="Permalink to &quot;10.1 orientationAroundZAxis()&quot;">​</a></h3><p>输入 yaw 角，函数创建包外 <code>tf2::Quaternion</code>，调用 <code>setRPY(0, 0, angle)</code>，再用 <code>tf2::toMsg()</code> 输出 geometry Quaternion。</p><p>它只生成绕 Z 轴旋转，适合二维导航方向。</p><h3 id="_10-2-euclidean-distance-四个重载" tabindex="-1">10.2 euclidean_distance() 四个重载 <a class="header-anchor" href="#_10-2-euclidean-distance-四个重载" aria-label="Permalink to &quot;10.2 euclidean_distance() 四个重载&quot;">​</a></h3><p>Point 版输入两个三维点。默认只计算 <code>hypot(dx, dy)</code>；<code>is_3d=true</code> 时加入 dz。</p><p>Pose 版只读取两个 Pose 的 position，忽略 orientation。</p><p>PoseStamped 版忽略 Header，转发给 Pose 版。它不会验证两个 Pose 是否处于同一 frame；调用者必须先完成 TF 变换。</p><p>Pose2D 版计算 x、y 平面距离，忽略 theta。</p><p>四个重载的输出都是 double L2 距离。</p><h3 id="_10-3-min-by" tabindex="-1">10.3 min_by() <a class="header-anchor" href="#_10-3-min-by" aria-label="Permalink to &quot;10.3 min_by()&quot;">​</a></h3><p>模板输入迭代器区间和 Getter。空区间返回 end；非空时对每个元素调用 Getter，输出比较值最小的元素迭代器。</p><p>相同最小值时保留最早出现的元素，因为更新条件是严格小于。</p><h3 id="_10-4-first-after-integrated-distance" tabindex="-1">10.4 first_after_integrated_distance() <a class="header-anchor" href="#_10-4-first-after-integrated-distance" aria-label="Permalink to &quot;10.4 first_after_integrated_distance()&quot;">​</a></h3><p>该模板输入 begin、end 和一个数值阈值，逐段调用 <code>euclidean_distance(*it, *(it+1))</code> 累加。累计距离严格大于阈值时，输出后一元素迭代器；始终未超过就返回 end。</p><p>模板参数名叫 Getter，实际被当作距离数值类型，还被用于声明累计变量。实现使用 <code>end-1</code> 和 <code>it+1</code>，因此调用者需要提供随机访问迭代器，普通链表迭代器不能使用。</p><h3 id="_10-5-calculate-path-length" tabindex="-1">10.5 calculate_path_length() <a class="header-anchor" href="#_10-5-calculate-path-length" aria-label="Permalink to &quot;10.5 calculate_path_length()&quot;">​</a></h3><p>输入 Path 与可选 start index。剩余 Pose 少于两个时输出 0；否则从 start 开始累加相邻 Pose 的二维距离。</p><p>函数不检查 Header frame，也不把闭合路径的末点连回起点。</p><h3 id="_10-6-lineiterator" tabindex="-1">10.6 LineIterator() <a class="header-anchor" href="#_10-6-lineiterator" aria-label="Permalink to &quot;10.6 LineIterator()&quot;">​</a></h3><p><code>LineIterator(x0, y0, x1, y1)</code> 初始化 Bresenham 参数。它根据 x、y 增减方向设置步进符号，再根据主方向是 x 还是 y 选择分母、分子增量和总像素数。</p><p>构造后当前坐标就是起点。终点也包含在合法迭代范围中。</p><h3 id="_10-7-isvalid-与-advance" tabindex="-1">10.7 isValid() 与 advance() <a class="header-anchor" href="#_10-7-isvalid-与-advance" aria-label="Permalink to &quot;10.7 isValid() 与 advance()&quot;">​</a></h3><p><code>isValid()</code> 输出 <code>curpixel_&lt;=numpixels_</code>，所以调用者常用 <code>for</code> 循环处理当前格，再 advance。</p><p><code>advance()</code> 更新误差分子；误差越过分母时同时沿次方向移动，然后沿主方向移动，最后像素计数加一。</p><h3 id="_10-8-六个坐标-getter" tabindex="-1">10.8 六个坐标 Getter <a class="header-anchor" href="#_10-8-六个坐标-getter" aria-label="Permalink to &quot;10.8 六个坐标 Getter&quot;">​</a></h3><p><code>getX()</code>、<code>getY()</code> 返回当前栅格坐标。</p><p><code>getX0()</code>、<code>getY0()</code> 返回构造输入起点。</p><p><code>getX1()</code>、<code>getY1()</code> 返回构造输入终点。</p><p>这些 Getter 都按值返回，不允许外部修改迭代器内部状态。Costmap 碰撞检查器可以用它逐格检查一条边，而无需浮点插值。</p><h2 id="十一、validate-messages-结构合法不等于业务安全" tabindex="-1">十一、validate_messages：结构合法不等于业务安全 <a class="header-anchor" href="#十一、validate-messages-结构合法不等于业务安全" aria-label="Permalink to &quot;十一、validate_messages：结构合法不等于业务安全&quot;">​</a></h2><h3 id="_11-1-validatemsg-double-与数组模板" tabindex="-1">11.1 validateMsg(double) 与数组模板 <a class="header-anchor" href="#_11-1-validatemsg-double-与数组模板" aria-label="Permalink to &quot;11.1 validateMsg(double) 与数组模板&quot;">​</a></h3><p>double 版只检查值不是 Inf、不是 NaN，输出 bool。</p><p><code>validateMsg(std::array&lt;double, N&gt;)</code> 对数组每个元素调用 double 版，任一失败立即返回 false。它主要用于协方差等定长浮点数组。</p><h3 id="_11-2-time、header-与-point" tabindex="-1">11.2 Time、Header 与 Point <a class="header-anchor" href="#_11-2-time、header-与-point" aria-label="Permalink to &quot;11.2 Time、Header 与 Point&quot;">​</a></h3><p>Time 版只要求 <code>nanosec&lt;1,000,000,000</code>。它不限制 sec 的正负。</p><p>Header 版要求 stamp 合法且 frame_id 非空。</p><p>Point 版要求 x、y、z 全部有限。</p><h3 id="_11-3-quaternion" tabindex="-1">11.3 Quaternion <a class="header-anchor" href="#_11-3-quaternion" aria-label="Permalink to &quot;11.3 Quaternion&quot;">​</a></h3><p>Quaternion 版先验证 x、y、z、w 有限，再计算四个分量平方和。该值与 1 的差不超过 <code>1e-4</code> 才返回 true。</p><p>它验证单位四元数，但不自动归一化输入。</p><h3 id="_11-4-pose-与带协方差-pose" tabindex="-1">11.4 Pose 与带协方差 Pose <a class="header-anchor" href="#_11-4-pose-与带协方差-pose" aria-label="Permalink to &quot;11.4 Pose 与带协方差 Pose&quot;">​</a></h3><p>Pose 版组合 Point 与 Quaternion 校验。</p><p>PoseWithCovariance 版要求 Pose 合法，并要求 36 项 covariance 全部有限。</p><p>PoseWithCovarianceStamped 版再叠加 Header 校验。</p><p>这组函数通过逐层组合减少重复逻辑，输出仍只有 bool，不返回失败字段的位置或原因。</p><h3 id="_11-5-mapmetadata-与-occupancygrid" tabindex="-1">11.5 MapMetaData 与 OccupancyGrid <a class="header-anchor" href="#_11-5-mapmetadata-与-occupancygrid" aria-label="Permalink to &quot;11.5 MapMetaData 与 OccupancyGrid&quot;">​</a></h3><p>MapMetaData 版验证 origin Pose、resolution 有限、height 和 width 非零。它没有要求 resolution 大于零，因此负分辨率也会通过。</p><p>OccupancyGrid 版验证 Header、MapMetaData，并要求 <code>data.size()==height×width</code>。它不检查每个栅格值是否处于 -1 或 0～100。</p><p>另一个编译边界是：多个非模板 <code>validateMsg()</code> 自由函数直接定义在头文件中，但没有显式 <code>inline</code>。如果多个翻译单元包含并链接这些定义，存在违反单一定义规则的风险。</p><h2 id="十二、字符串、计时与小型接口" tabindex="-1">十二、字符串、计时与小型接口 <a class="header-anchor" href="#十二、字符串、计时与小型接口" aria-label="Permalink to &quot;十二、字符串、计时与小型接口&quot;">​</a></h2><h3 id="_12-1-strip-leading-slash" tabindex="-1">12.1 strip_leading_slash() <a class="header-anchor" href="#_12-1-strip-leading-slash" aria-label="Permalink to &quot;12.1 strip_leading_slash()&quot;">​</a></h3><p>输入字符串以 <code>/</code> 开头时，<code>strip_leading_slash()</code> 只删除首个字符。<code>//map</code> 会输出 <code>/map</code>，不是 <code>map</code>；空字符串原样返回。</p><h3 id="_12-2-split" tabindex="-1">12.2 split() <a class="header-anchor" href="#_12-2-split" aria-label="Permalink to &quot;12.2 split()&quot;">​</a></h3><p><code>split(tokenstring, delimiter)</code> 从左到右查找单字符分隔符，把各段放入 Tokens vector。</p><p>连续分隔符会产生空 token，尾部分隔符也会产生末尾空 token；空输入得到包含一个空字符串的 vector。这正是生命周期字符串接口可能收到空节点名的原因。</p><h3 id="_12-3-executiontimer-的四个方法" tabindex="-1">12.3 ExecutionTimer 的四个方法 <a class="header-anchor" href="#_12-3-executiontimer-的四个方法" aria-label="Permalink to &quot;12.3 ExecutionTimer 的四个方法&quot;">​</a></h3><p><code>start()</code> 把 high_resolution_clock 当前时刻写入 <code>start_</code>。</p><p><code>end()</code> 把当前时刻写入 <code>end_</code>。</p><p><code>elapsed_time()</code> 输出 <code>end_-start_</code> 的整数纳秒 duration。</p><p><code>elapsed_time_in_seconds()</code> 把同一时间差转成 double 秒。</p><p>它不自动 start／end，也不验证调用顺序；未先设置时间点就读取结果，没有业务意义。high_resolution_clock 是否等同 steady clock 由标准库实现决定，因此它适合局部耗时观测，不应直接替代 ROS 时间。</p><h2 id="十三、包外调用-一行工具函数背后的真实系统" tabindex="-1">十三、包外调用：一行工具函数背后的真实系统 <a class="header-anchor" href="#十三、包外调用-一行工具函数背后的真实系统" aria-label="Permalink to &quot;十三、包外调用：一行工具函数背后的真实系统&quot;">​</a></h2><h3 id="_13-1-rclcpp-与-executor" tabindex="-1">13.1 rclcpp 与 Executor <a class="header-anchor" href="#_13-1-rclcpp-与-executor" aria-label="Permalink to &quot;13.1 rclcpp 与 Executor&quot;">​</a></h3><p>本包调用 rclcpp 创建 Node、Subscription、Client、CallbackGroup、SingleThreadedExecutor、参数与 Context 回调。</p><p>数据不是“调用函数就立即得到”的：</p><ul><li>Subscription 数据由包外 DDS 与 Executor 送入 <code>odomCallback()</code>。</li><li>Service Response 由 Client Future 表示，再由局部 Executor 推进完成。</li><li>PreShutdown 回调由 rclcpp Context 在 shutdown 序列中触发。</li><li>NodeThread 只负责调度，不产生业务结果。</li></ul><h3 id="_13-2-rclcpp-action" tabindex="-1">13.2 rclcpp_action <a class="header-anchor" href="#_13-2-rclcpp-action" aria-label="Permalink to &quot;13.2 rclcpp_action&quot;">​</a></h3><p>Action Server 的 Goal、Cancel、Feedback 与 Result 协议由包外 rclcpp_action 实现。<code>SimpleActionServer</code> 只在其上维护 current／pending 槽和业务工作线程。</p><p>因此 Planner Server 或 Controller Server 调用 <code>succeeded_current()</code> 时，真正把 Result 发送给远端 Action Client 的是 GoalHandle；Nav2 工具层只选择何时调用它。</p><h3 id="_13-3-tf2-与-tf2-ros" tabindex="-1">13.3 tf2 与 tf2_ros <a class="header-anchor" href="#_13-3-tf2-与-tf2-ros" aria-label="Permalink to &quot;13.3 tf2 与 tf2_ros&quot;">​</a></h3><p>TF Buffer 的数据来自系统中的 Transform Broadcaster。<code>getCurrentPose()</code> 不订阅里程计，也不自己积分位置，而是查询 Buffer 中已经建立的坐标关系。</p><p>Lookup 失败可能来自 frame 不存在、TF 树不连通、请求时间超出缓存或等待超时。本包把这些异常转成日志和 false，调用者决定重试、终止 Goal 还是继续等待。</p><h3 id="_13-4-bondcpp-与-lifecycle-msgs" tabindex="-1">13.4 bondcpp 与 lifecycle_msgs <a class="header-anchor" href="#_13-4-bondcpp-与-lifecycle-msgs" aria-label="Permalink to &quot;13.4 bondcpp 与 lifecycle_msgs&quot;">​</a></h3><p>Bond 是进程／节点存活通道，Lifecycle Service 是状态控制通道。二者不是同一件事：</p><ul><li>ChangeState 决定 configure、activate、deactivate、cleanup。</li><li>GetState 读取当前状态。</li><li>Bond 在节点 ACTIVE 后周期证明“我还活着”。</li></ul><p>Lifecycle Manager 同时使用这两条通道，才能区分“节点处于什么状态”和“节点进程是否失联”。</p><h3 id="_13-5-消息包" tabindex="-1">13.5 消息包 <a class="header-anchor" href="#_13-5-消息包" aria-label="Permalink to &quot;13.5 消息包&quot;">​</a></h3><p><code>geometry_msgs</code> 提供 Pose、Point、Quaternion、Twist；<code>nav_msgs</code> 提供 Path、Odometry、OccupancyGrid；<code>nav2_msgs</code> 提供 Nav2 Costmap 和清图服务。</p><p><code>nav2_util</code> 不改变这些消息的 IDL，只做验证、转换、累计或同步调用。跨包接口变更仍要以消息包定义为准。</p><h2 id="十四、读完源码后必须记住的边界" tabindex="-1">十四、读完源码后必须记住的边界 <a class="header-anchor" href="#十四、读完源码后必须记住的边界" aria-label="Permalink to &quot;十四、读完源码后必须记住的边界&quot;">​</a></h2><h3 id="_14-1-封装名不等于业务成功" tabindex="-1">14.1 封装名不等于业务成功 <a class="header-anchor" href="#_14-1-封装名不等于业务成功" aria-label="Permalink to &quot;14.1 封装名不等于业务成功&quot;">​</a></h3><p><code>LifecycleServiceClient::change_state()</code> 返回的 true 只表示拿到了非空 Response，不代表 Response 的 <code>success</code> 字段为 true。</p><p><code>ServiceClient::invoke()</code> 的 timeout 不覆盖“等待服务出现”的阶段。</p><p><code>SimpleActionServer::handle_cancel()</code> 接受取消，也不代表业务线程已经停下；execute callback 必须主动响应。</p><h3 id="_14-2-并发安全依赖调用方式" tabindex="-1">14.2 并发安全依赖调用方式 <a class="header-anchor" href="#_14-2-并发安全依赖调用方式" aria-label="Permalink to &quot;14.2 并发安全依赖调用方式&quot;">​</a></h3><p>SimpleActionServer 大部分 Handle 操作使用递归互斥锁，但 <code>publish_feedback()</code> 没有持锁。</p><p>OdomSmoother 写路径加锁，两个 Getter 不加锁。</p><p>NodeThread 析构会 cancel 并 join，生命周期与销毁线程必须由调用者安排。</p><h3 id="_14-3-数据合法性校验不是范围校验" tabindex="-1">14.3 数据合法性校验不是范围校验 <a class="header-anchor" href="#_14-3-数据合法性校验不是范围校验" aria-label="Permalink to &quot;14.3 数据合法性校验不是范围校验&quot;">​</a></h3><p><code>validateTwist()</code> 只排除 NaN 与 Inf。</p><p><code>validateMsg(MapMetaData)</code> 不保证正分辨率，OccupancyGrid 校验不检查每个栅格值。</p><p>Costmap 的坐标查询不做边界检查，非三值代价缩放还存在整数除法边界。</p><h3 id="_14-4-公共底座的真正价值" tabindex="-1">14.4 公共底座的真正价值 <a class="header-anchor" href="#_14-4-公共底座的真正价值" aria-label="Permalink to &quot;14.4 公共底座的真正价值&quot;">​</a></h3><p><code>nav2_util</code> 没有替 Nav2 做规划、控制或恢复决策。它做的是更底层、也更容易在多个包中写错的事情：</p><ul><li>把 Lifecycle 状态、Bond 与退出清理接起来。</li><li>把异步 Action 整理成 current／pending 和业务工作线程。</li><li>把 ROS 2 Service Future 包成同步调用。</li><li>把 TF、Odometry、路径距离和栅格射线变成可直接复用的接口。</li><li>把参数声明、内部 Node 与消息结构校验统一起来。</li></ul><p>所以，读 Planner 或 Controller 时看到一行 <code>nav2_util</code> 调用，不能把它当作无关紧要的辅助函数。那一行常常正是跨线程、跨节点、跨时间或跨坐标系的数据边界。</p><p>理解这 128 个入口后，Nav2 各服务器之间那些看似重复却行为一致的 Lifecycle、Action、TF 和参数代码，也就真正连成了一套系统。</p>',339)])])}const q=a(p,[["render",u]]);export{v as __pageData,q as default};
